arguments.command:
cd /tmp/vally-eval-trial-Nnd0jW && export PYTHONPATH=$PWD/src && P=.venv/bin/python3 && S=/tmp/cr-core.sqlite && rm -f $S && $P -m pytest -q -p no:cacheprovider tests/unit 2>&1 | tail -3 && $P -m cosmic_ray.cli init cosmic-ray-core.toml $S && $P -m cosmic_ray.cli exec cosmic-ray-core.toml $S 2>&1 | tail -3; $P -m cosmic_ray.tools.survival_rate $S; $P -m cosmic_ray.cli dump $S | $P -c "
import sys,json
for l in sys.stdin:
    j,r=json.loads(l)
    if r['test_outcome']!='killed': print(r['test_outcome'],j['module_path'],[(m['operator_name'],m['start_pos'],m['occurrence']) for m in j['mutations']])
"; git status --short

